# scripts\test-5hour-reminder.ps1
Set-Location $PSScriptRoot\..

node -e "require('dotenv').config(); const mongoose = require('mongoose'); (async () => { try { await mongoose.connect(process.env.MONGODB_URI); console.log('✅ Connected'); const User = require('./models/User'); const Appointment = require('./models/Appointment'); const patientUser = await User.findOne({ role: 'patient' }); if (!patientUser) { console.log('❌ No patient found in DB'); process.exit(1); } console.log('👤 Using patient:', patientUser.name, patientUser.email, patientUser._id); const d = new Date(); d.setHours(d.getHours() + 5); const dateOnly = new Date(d); dateOnly.setHours(0,0,0,0); const appt = await Appointment.create({ patientId: patientUser._id, patientName: patientUser.name, patientEmail: patientUser.email, patientPhone: '0814725897', date: dateOnly, time: d.getHours().toString().padStart(2,'0') + ':' + d.getMinutes().toString().padStart(2,'0'), description: 'Test appointment for 5h reminder', status: 'pending', fiveHourReminderSent: false }); console.log('✅ Created test appointment:', appt._id); console.log('   Scheduled for:', d.toLocaleString()); process.exit(0); } catch (err) { console.error('❌ Error:', err.message); process.exit(1); } })();"